"""Deterministic original gameplay catalog; NASA supplies context, not equipment specs."""
from pathlib import Path
import json,copy
root=Path(__file__).resolve().parents[1]
p=root/'game/assets/OUTPOST_CATALOG.json'
base=[x for x in json.loads(p.read_text())['items'] if '__' not in x['id'] and x.get('family',x['id'])==x['id'] and x['category'] not in ['Launch','Gear','Traversal','Safety']]
base=base[:20]
mods=[('standard','Standard',1,1,1,1,1,1),('compact','Compact',.7,.65,.72,.75,.8,1),('expedition','Expedition',1.45,1.35,1.4,1.15,1.15,1.25),('cold','Cryogenic',1.4,1.2,1.05,1.15,1,1.8),('dust','Dust-sealed',1.35,1.15,1.05,1,1.1,2.2),('efficient','High-efficiency',1.7,1.1,1.2,.65,1.15,1.1),('survey','Survey-grade',1.8,1.3,1.05,1.25,1.7,1.2),('rugged','Rugged',1.55,1.7,1.15,1.25,1.1,2.8)]
items=[]
for b in base:
 for mi,(suffix,title,cost,mass,output,draw,reach,durability) in enumerate(mods):
  x=copy.deepcopy(b);x.update(id=b['id'] if mi==0 else b['id']+'__'+suffix,family=b['id'],variant=suffix,capacityFactor=output,reachFactor=reach,durability=durability,researchRate=reach,efficiency=1/draw)
  x.update(cost=round(b['cost']*cost),mass=round(b['mass']*mass,1),output=round(b['output']*output,2),draw=round(b['draw']*draw,2))
  if mi:x['name']=b['name']+' / '+title;x['description']+=f' {title}: altered mass, price, throughput, efficiency, operating reach and durability.'
  x['recipe']={k:max(1,round(v*cost)) for k,v in b['recipe'].items()};items.append(x)
utilities=[('anchor','PINION / climbing anchor',25,4,.5,0,'Mountaineering belay point and rope attachment; requires suitable stable ground.'),('winch','DESCENT / powered belay winch',65,12,.9,1,'Powered climbing assistance with a braking drum for steep routes.'),('ropebridge','CATENARY / rope suspension kit',55,10,1.2,0,'Consumes a kit to connect two anchors with an actual collision walkway.'),('floodlight','LUMEN / cave floodlight',25,5,.8,.5,'Illuminates cave work zones and warns of nearby shafts.'),('shelter','AEGIS / radiation refuge',95,32,2,1.5,'A local shelter that reduces simulated radiation and cold exposure.'),('scrubber','PURE / dust-service station',45,10,1,1.5,'Removes accumulated suit contamination near a powered station.'),('heater','CALOR / thermal service',45,12,1,2,'Powered thermal protection around a remote camp.'),('oxygen_cache','BREATH / reserve manifold',35,8,.8,0,'A finite emergency oxygen cache; does not create oxygen.'),('repair_station','MENDER / maintenance rig',55,14,1.2,2,'Consumes alloy to restore suit integrity near a powered rig.'),('survey_lidar','VECTOR / scanning tripod',70,13,1,1.5,'Research instrument for mapping complex relief; requires power and downlink.'),('sample_vault','ARCHIVE / cryogenic sample vault',65,17,1.2,1,'Cold-protected sample research; research needs power and communication.'),('radiometer','RAD / exposure observatory',65,11,1.1,1,'Radiation-context research and powered local exposure protection.')]
for fid,name,cost,mass,radius,draw,desc in utilities:
 for idx,mod in enumerate(mods[:4]):
  suffix,title,c,m,o,d,r,wear=mod
  items.append(dict(id=fid if idx==0 else fid+'__'+suffix,family=fid,variant=suffix,name=name+(' / '+title if idx else ''),category='Traversal' if fid in ['anchor','winch','ropebridge','floodlight'] else 'Safety',cost=round(cost*c),mass=round(mass*m,1),radius=radius,draw=round(draw*d,2),output=0,tier=1 if idx<2 else 2,recipe={'alloy':max(1,round(cost/15*c)),'circuits':max(1,round(mass/5*c)),'polymer':2},description=desc,capacityFactor=o,reachFactor=r,durability=wear,researchRate=r,efficiency=1/d))
gear=[('harness','Rated climbing harness',50,2,'Climbing'),('crampons','Regolith traction crampons',40,3,'Climbing'),('rope30','30 m static rope',35,3,'Rope'),('rope60','60 m static rope',65,6,'Rope'),('ascender','Mechanical rope ascender',55,2,'Climbing'),('headlamp','EVA headlamp',25,1,'Cave light'),('lidar','Handheld rangefinder',65,2,'Mapping'),('radiation_liner','Radiation shelter liner',90,5,'Radiation'),('thermal_liner','Cold-region thermal liner',65,4,'Thermal'),('dust_filter','Replaceable dust filter',30,1,'Dust'),('oxygen_bottle','Emergency oxygen bottle',40,3,'Oxygen'),('medkit','Trauma and seal kit',45,2,'Medicine'),('sealant','Pressure-seal cartridge',25,1,'Repair'),('spare_cell','Portable battery cell',35,3,'Power'),('sample_container','Sterile sample container',20,1,'Sampling'),('navigation','Inertial route recorder',45,2,'Navigation')]
for fid,name,cost,mass,purpose in gear:items.append(dict(id=fid,family=fid,variant='standard',name=name,category='Gear',cost=cost,mass=mass,radius=.4,draw=0,output=0,tier=1,recipe={'alloy':1,'circuits':1,'polymer':2},description=purpose+' equipment. Carrying/equipping this item enables its field interaction; consumables are spent when used.',portable=True,capacityFactor=1,reachFactor=1,durability=1,researchRate=1))
rockets=[('launch_core','Launch vehicle core',180,True),('rocket_engine','Propulsion engine cluster',240,True),('rocket_fuel','Propellant allocation',160,True),('rocket_guidance','Guidance and inertial unit',140,True),('rocket_shield','Mars entry thermal shield',160,True),('rocket_capsule','Crew pressure capsule',220,True),('rocket_lander','Terminal descent module',220,True),('rocket_radar','Landing radar',100,True),('rocket_radiation','Transit storm shelter',100,False),('rocket_redundancy','Redundant avionics',90,False),('rocket_recovery','Descent contingency kit',80,False),('rocket_supply','Transit consumable reserve',70,False)]
for fid,name,cost,required in rockets: items.append(dict(id=fid,family=fid,variant='flight',name=name,category='Launch',cost=cost,mass=0,launchMass=cost*18,radius=1.5,draw=0,output=0,tier=1,recipe={},description=('Required' if required else 'Optional resilience upgrade')+' for the expedition rocket. Delivered to vehicle integration rather than the field backpack. Speculative gameplay sizing.',required=required,rocket=True,capacityFactor=1,reachFactor=1,durability=1,researchRate=1))
assert len(items)==236 and len({i['id'] for i in items})==236
p.write_text(json.dumps({'version':2,'credits':3200,'capacityKg':260,'items':items,'note':'236 purchasable configurations: 32 deployable families with functional variants, 16 portable tools/consumables and 12 launch components. All specs/economics are game models.'},indent=2))
print('Catalog:',len(items),'configurations; rocket required cost',sum(r[2] for r in rockets if r[3]))
